        '#ec-ov .hero{background:linear-gradient(135deg,rgba(91,141,239,.18),rgba(91,141,239,.04));border:1px solid var(--line);border-radius:.8em;padding:1.1em 1.4em}',
        '#ec-ov .hero h3{font-size:1.5em}',
