            if (BOOK.authors && BOOK.authors.length) { bits.push(BOOK.authors.join(', ')); }
            if (BOOK.publisher) { bits.push(BOOK.publisher); }
            if (BOOK.publishedDate) { bits.push(String(BOOK.publishedDate).slice(0, 4)); }
            if (BOOK.price) { bits.push(BOOK.price); }
            sub.textContent = bits.join(' \xB7 ');
